import sys
MOD=998244353
def solve():
    raw=sys.stdin.read().split()
    if not raw:
        return
    it=iter(raw)
    t=int(next(it))
    ot=[]
    for _ in range(t):
        n=int(next(it))
        a=[int(next(it)) for _ in range(n)]
        ps=[[] for _ in range(n+1)]
        for i,v in enumerate(a,1):
            ps[v].append(i)
        dp=[0]*(n+1)
        dp[0]=1
        for v in range(1,n):
            ndp=[0]*(n+1)
            for x in range(v):
                if dp[x]==0:
                    continue
                r=v-1-x
                l1=r1=True
                for i in ps[v]:
                    pr=min(x,i)+max(0,i-n+r)
                    suf=max(0,x-i+1)+min(r,n-i+1)
                    if not ((x+1<=i and pr==(i-1)//2) or (x+1>=i and suf==(n-i)//2)):
                        l1=False
                    if not ((n-r<=i and pr==(i-1)//2) or (n-r>=i and suf==(n-i)//2)):
                        r1=False
                    if not l1 and not r1:
                        break
                if l1 :
                    ndp[x+1]=(ndp[x+1]+dp[x])%MOD
                if r1:
                    ndp[x]=(ndp[x]+dp[x])%MOD
            dp=ndp
        an=0
        for x in range(n):
            if dp[x]==0:
                continue
            r=n-1-x
            o=True
            for i in ps[n]:
                pr=min(x,i)+max(0,i-n+r)
                suf=max(0,x-i+1)+min(r,n-i+1)
                if not ((x+1<=i and pr==(i-1)//2) or (x+1>=i and suf==(n-i)//2)):
                    o=False
                    break
            if o :
                an=(an+dp[x])%MOD
        ot.append(str(an))
    sys.stdout.write('\n'.join(ot)+'\n')
    
solve()
